/* PANEL-01 · Mi Panel. Solo colores vía tokens: ningún literal de color. */

.body {
  min-height: 100%;
  padding: var(--bw-pad-panel);
  background: var(--bw-cold-white);
  font-family: var(--bw-font-body);
}

.inner {
  max-width: 820px;
}

.eyebrow {
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-eyebrow);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-eyebrow);
  color: var(--bw-calibration-blue);
  margin-bottom: 8px;
}

.title {
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-title);
  font-weight: 700;
  letter-spacing: var(--bw-ls-title);
  color: var(--bw-deep-steel);
  line-height: 1.2;
  margin: 0 0 4px;
}

.sub {
  font-size: var(--bw-size-body);
  color: var(--bw-text-secondary);
  line-height: 1.6;
  max-width: 600px;
  margin: 0 0 24px;
}

.loading,
.error {
  font-size: var(--bw-size-body);
  line-height: 1.6;
}

.loading {
  color: var(--bw-text-secondary);
}

.error {
  color: var(--bw-error-text);
}

/* ── Rejilla de tarjetas ─────────────────────────────────────────────── */
.grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
  max-width: 820px;
}

@media (max-width: 720px) {
  .grid {
    grid-template-columns: 1fr;
  }
}

.card {
  display: flex;
  flex-direction: column;
  gap: 6px;
  width: 100%;
  padding: 18px 20px;
  appearance: none;
  /* El HTML aprobado usa blanco puro (#fff), que no existe como token de
     superficie: se usa el neutro de superficie clara más cercano del sistema. */
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  /* El mock aprobado usa 10px; el token del sistema (--bw-radius) son 3px
     y dejaría la tarjeta demasiado cuadrada, así que se mantiene el radio
     del diseño aprobado. */
  border-radius: 10px;
  color: var(--bw-deep-steel);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-body);
  text-align: left;
  cursor: pointer;
  transition:
    box-shadow 0.15s ease,
    border-color 0.15s ease;
}

.card:hover {
  border-color: var(--bw-line-steel-strong);
  /* No hay token de sombra de tarjeta en el sistema: se usa el gris
     translúcido más cercano que ya existe (--bw-scroll-thumb). */
  box-shadow: 0 4px 14px var(--bw-scroll-thumb);
}

.card:focus-visible {
  outline: none;
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
}

.cardWide {
  grid-column: 1 / -1;
}

.cardHeader {
  display: flex;
  align-items: center;
  gap: 9px;
}

.icon {
  width: 32px;
  height: 32px;
  /* El mock aprobado usa 7px para el icono; no hay token para ese radio. */
  border-radius: 7px;
  background: var(--bw-icon-tint-blue);
  color: var(--bw-calibration-blue);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 17px;
  flex-shrink: 0;
}

.cardTitle {
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-input);
  font-weight: 700;
  color: var(--bw-deep-steel);
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-label);
}

.num {
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-title);
  font-weight: 700;
  color: var(--bw-deep-steel);
  line-height: 1;
}

.label {
  font-size: var(--bw-size-label);
  color: var(--bw-text-secondary);
}

.detail,
.invLine {
  font-size: var(--bw-size-input);
  color: var(--bw-ink-steel);
  line-height: 1.5;
}

.detail b,
.invLine b {
  color: var(--bw-deep-steel);
  font-weight: 600;
}

.metricsRow {
  display: flex;
  gap: 32px;
}

.metric {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

@media (max-width: 520px) {
  .metricsRow {
    flex-direction: column;
    gap: 14px;
  }
}

